function makeWeapon(classId) {
  const g = new THREE.Group();
  if (classId === 'panzer') {
    const handle = mesh(new THREE.CylinderGeometry(.08,.1,1.25,8), mat(0x65422b)); handle.rotation.x = Math.PI / 2; handle.position.z = .62; g.add(handle);
    const spring = mesh(new THREE.TorusGeometry(.16,.04,5,10), mat(0x8a94a5)); spring.rotation.x = Math.PI / 2; spring.scale.z = 2; spring.position.z = 1.25; g.add(spring);
    const pan = mesh(new THREE.CylinderGeometry(.55,.46,.16,16), mat(0x29323c)); pan.rotation.x = Math.PI / 2; pan.position.z = 1.55; g.add(pan);
  } else if (classId === 'pun-slinger') {
    const bread = mesh(new THREE.CapsuleGeometry(.19,.95,5,10), mat(0xe0a34c)); bread.rotation.x = Math.PI / 2; bread.position.z = .7; g.add(bread);
    for (let z=.35;z<1.1;z+=.25) { const score = mesh(new THREE.BoxGeometry(.25,.025,.025),mat(0x9b6234),false); score.position.set(0,.19,z); score.rotation.z=.4; g.add(score); }
  } else {
    const shaft = mesh(new THREE.CylinderGeometry(.09,.11,1.35,8), mat(0x72869b)); shaft.rotation.x = Math.PI/2; shaft.position.z=.62; g.add(shaft);
    for(let i=0;i<4;i++){ const fold=mesh(new THREE.BoxGeometry(.45,.32,.09),mat(i%2?0xb76a68:0xe2b86e)); fold.position.z=1.22+i*.1; fold.rotation.z=(i%2?-.12:.12); g.add(fold); }
  }
  g.position.set(.65,1.2,.28); g.rotation.set(.1,0,-.35); return g;
}

