  g.userData.rigBinding={version:1,root:g,body:g.userData.parts.body,head:g.userData.parts.head,leftArm:g.userData.parts.arms[0],rightArm:g.userData.parts.arms[1],legs:g.userData.parts.legs,weapon,actionCue};
