function syncPondMemories() {
  if (!scene || !save) return;
  const colors = { 'gossip-carp': 0xf2ad67, 'moon-eel': 0x87a9ff, 'argument-tuna': 0xd8799b };
  (save.world.pondSpecies || []).forEach((id, index) => {
    if (pondMemories.some(entry => entry.userData.pondSpecies === id)) return;
    const angle = -.9 + index * .9;
    const g = new THREE.Group();
    const body = mesh(new THREE.SphereGeometry(.48, 10, 7), mat(colors[id] || 0x79c6b4));
    body.scale.set(1.45, .65, .55); body.position.y = 1.12; g.add(body);
    const tail = mesh(new THREE.ConeGeometry(.34, .7, 6), mat(colors[id] || 0x79c6b4));
    tail.rotation.z = Math.PI / 2; tail.position.set(-.82, 1.12, 0); g.add(tail);
    const eye = mesh(new THREE.SphereGeometry(.055, 6, 4), mat(0x17243a), false);
    eye.position.set(.5, 1.24, .25); g.add(eye);
    const plaque = mesh(new THREE.BoxGeometry(1.5, .15, .75), mat(0x8a6845)); plaque.position.y = .12; g.add(plaque);
    g.position.set(62 + Math.cos(angle) * 6.2, 0, -72 + Math.sin(angle) * 5.1);
    g.rotation.y = -angle + .4; g.userData.pondSpecies = id; scene.add(g); pondMemories.push(g);
    if (id === 'moon-eel') { const beacon = new THREE.PointLight(0x8daeff, 2.2, 10); beacon.position.set(0, 2.1, 0); g.add(beacon); }
  });
}

