function placeAdventureWitnesses(){villageCitizens.forEach(citizen=>{const aftermath=adventureAftermathForCitizen(citizen);if(!aftermath)return;const status=S.aftermathStatus(save,aftermath,D.storyChoices);if(!status.available)return;const at=adventureAftermathPosition(aftermath,status),it=citizen.userData.routine.interactable;citizen.position.set(at.x,0,at.z);if(it){it.x=at.x;it.z=at.z;it.marker.position.x=at.x;it.marker.position.z=at.z;}});}

function updateAdventureWitness(citizen,dt,time){const aftermath=adventureAftermathForCitizen(citizen);if(!aftermath)return;const status=S.aftermathStatus(save,aftermath,D.storyChoices),routine=citizen.userData.routine,it=routine.interactable;if(!status.available)return;const helped=Boolean(save.world.villageFavors?.[aftermath.witnessId]),reportMode=!status.heardCurrent||helped;if(it){it.kind=reportMode?'aftermath':'favor';it.label=reportMode?(status.heardCurrent?'Revisit ':'Hear ')+aftermath.witness+' report':'Help '+aftermath.witness;}
  const daytime=save.world.worldMinute>=360&&save.world.worldMinute<1200,threat=enemies.some(enemy=>!enemy.userData.dead&&enemy.position.distanceTo(citizen.position)<11);if(daytime&&!threat){routine.status=status.heardCurrent?'PUBLIC MEMORY - '+status.title.toUpperCase():'WITNESS REPORT - NEW';const at=adventureAftermathPosition(aftermath,status),target=temp2.set(at.x,0,at.z),distance=citizen.position.distanceTo(target),nearHero=hero&&hero.position.distanceTo(citizen.position)<4.4;if(!nearHero&&distance>.25){temp.copy(target).sub(citizen.position).setY(0).normalize();citizen.position.addScaledVector(temp,1.35*dt);citizen.rotation.y=Math.atan2(temp.x,temp.z);}else{citizen.position.y=Math.abs(Math.sin(time*3+citizen.userData.phase))*.035;routine.prop.rotation.y+=dt*.8;}}if(it){it.x=citizen.position.x;it.z=citizen.position.z;}
}

function buildVillageLife(){D.villageLife.forEach((definition,index)=>{const citizen=definition.race==='robot'?makeRobot({name:definition.name,role:definition.role,color:definition.color},.72):makeVillager(definition.name,definition.race,definition.color);const prop=makeCitizenProp(definition);citizen.add(prop);citizen.position.set(definition.home[0],0,definition.home[1]);citizen.userData.routine={definition,waypoint:1,dwell:1+index%3,cheer:0,panic:0,prop,status:'ROAMING'};scene.add(citizen);npcs.push(citizen);villageCitizens.push(citizen);const helped=Boolean(save.world.villageFavors?.[definition.id]),entry=makeInteractable('favor',definition.id,citizen.position.x,citizen.position.z,helped?'Check on '+definition.name:'Help '+definition.name,citizen,5.5);citizen.userData.routine.interactable=entry;});}

function buildGearCouncil(){const definition=D.gearCouncil,root=new THREE.Group(),base=mesh(new THREE.CylinderGeometry(4.3,4.65,.35,18),mat(0x314a63));base.position.y=.18;root.add(base);const table=mesh(new THREE.CylinderGeometry(1.65,1.85,.75,12),mat(0x8c6b50));table.position.y=.72;root.add(table);const argumentGear=mesh(new THREE.TorusGeometry(.72,.2,7,14),mat(0xffc95f,{emissive:0x6f4514,emissiveIntensity:.45}));argumentGear.rotation.x=Math.PI/2;argumentGear.position.y=1.28;root.add(argumentGear);const clerk=makeRobot({name:definition.clerk,role:'Contradiction Clerk',color:'#79c4d3'},.78);clerk.position.set(0,0,2.55);clerk.rotation.y=Math.PI;root.add(clerk);const terminals=[];definition.arguments.forEach((argument,index)=>{const angle=index/definition.arguments.length*Math.PI*2+.35,terminal=new THREE.Group(),body=mesh(new THREE.CylinderGeometry(.42,.58,.8,8),mat(new THREE.Color(argument.color)));body.position.y=.42;terminal.add(body);const receiver=mesh(new THREE.SphereGeometry(.24,8,6),mat(argument.color,{emissive:argument.color,emissiveIntensity:.25}),false);receiver.position.y=1.05;terminal.add(receiver);const antenna=mesh(new THREE.CylinderGeometry(.025,.035,.65,5),mat(0xd6e3e7),false);antenna.position.y=1.42;terminal.add(antenna);terminal.position.set(Math.cos(angle)*3,0,Math.sin(angle)*3);terminal.rotation.y=-angle+Math.PI/2;terminal.userData={receiver,phase:index*1.4};root.add(terminal);terminals.push(terminal);});root.position.set(definition.at[0],0,definition.at[1]);scene.add(root);const interactable=makeInteractable('gear-council',definition.id,definition.at[0],definition.at[1],'Inspect '+definition.name,root,7);gearCouncilStation={definition,root,argumentGear,clerk,terminals,interactable};syncGearCouncilStation();}

