function buildOriginEchoSites(){D.dropOrigins.forEach((definition,index)=>{const root=new THREE.Group(),base=mesh(new THREE.CylinderGeometry(2.15,2.45,.34,14),mat(0x35485b));base.position.y=.17;root.add(base);const gold=mesh(new THREE.TorusGeometry(1.35,.15,7,18),mat(0xffc95f,{emissive:0x6a4315,emissiveIntensity:.35}));gold.rotation.x=Math.PI/2;gold.position.y=.43;root.add(gold);const core=new THREE.Group(),accent=new THREE.Color(definition.color);if(definition.shape==='stamp'){const paper=mesh(new THREE.BoxGeometry(1.25,.12,.9),mat(0xf4e9cf));paper.position.y=.58;core.add(paper);const stamp=mesh(new THREE.CylinderGeometry(.38,.5,.72,10),mat(accent));stamp.position.y=1.05;stamp.rotation.z=.12;core.add(stamp);}else if(definition.shape==='bell'){const bell=mesh(new THREE.ConeGeometry(.62,.92,12),mat(accent));bell.rotation.x=Math.PI;bell.position.y=.95;core.add(bell);const clapper=mesh(new THREE.SphereGeometry(.16,7,5),mat(0xffdc73));clapper.position.y=.43;core.add(clapper);}else if(definition.shape==='rainbow'){for(let arc=0;arc<3;arc++){const rainbow=mesh(new THREE.TorusGeometry(.66+arc*.2,.09,6,18,Math.PI),mat([0xe97b89,0xe7bd5b,0x78c99a][arc]));rainbow.position.y=.55+arc*.16;rainbow.rotation.z=Math.PI;core.add(rainbow);}const drain=mesh(new THREE.CylinderGeometry(.5,.62,.12,12),mat(0x48676d));drain.position.y=.42;core.add(drain);}else if(definition.shape==='screw'){const shaft=mesh(new THREE.CylinderGeometry(.18,.18,1.25,9),mat(accent));shaft.position.y=.96;shaft.rotation.z=.55;core.add(shaft);const head=mesh(new THREE.CylinderGeometry(.47,.47,.22,10),mat(accent));head.position.set(-.36,1.5,0);head.rotation.z=.55;core.add(head);const slot=mesh(new THREE.BoxGeometry(.55,.05,.08),mat(0x27384a),false);slot.position.set(-.36,1.62,.02);slot.rotation.z=.55;core.add(slot);}else{for(let feather=0;feather<5;feather++){const plume=mesh(new THREE.ConeGeometry(.13,.78,6),mat(feather%2?0xfff1c2:accent));plume.position.set((feather-2)*.22,.8+Math.abs(feather-2)*.08,0);plume.rotation.z=(feather-2)*.22;core.add(plume);}}core.position.y=.05;root.add(core);const signal=mesh(new THREE.OctahedronGeometry(.27,0),mat(definition.color,{emissive:definition.color,emissiveIntensity:.35}),false);signal.position.y=2.15;root.add(signal);const light=new THREE.PointLight(definition.color,0,8,2);light.position.y=2;root.add(light);root.position.set(definition.at[0],0,definition.at[1]);scene.add(root);const interactable=makeInteractable('origin-echo',definition.id,definition.at[0],definition.at[1],'Inspect '+definition.title,root,6.5);originEchoSites.push({definition,root,gold,core,signal,light,interactable,phase:index*1.3});});syncOriginEchoSites();}

