    const lunch=mesh(new THREE.BoxGeometry(1.45,.9,.85),mat(0xd85e6f));lunch.position.set(0,.75,0);root.add(lunch);const handle=mesh(new THREE.TorusGeometry(.48,.08,6,10,Math.PI),mat(0x5d3b37));handle.rotation.x=Math.PI/2;handle.position.set(0,1.25,0);root.add(handle);
