      for(let i=0;i<definition.count;i++){const report=mesh(new THREE.SphereGeometry(.24,8,6),mat(i%2?0x8fcf83:0x8bb3df,{emissive:i%2?0x2f6947:0x354e7d,emissiveIntensity:.4}),false),angle=i/definition.count*Math.PI*2;report.scale.set(.72,1.4,.72);report.position.set(Math.cos(angle)*1.45,1+Math.sin(angle)*.28,Math.sin(angle)*1.45);report.visible=false;root.add(report);progressProps.push(report);}
