function syncWorldEventScenery(time=0){
  const omen=S.omenProgress(save),ruin=S.ruinStage(save);eventVisuals.forEach((entry,index)=>{const local=S.clamp((omen-entry.threshold)*5,0,1),forced=save.world.finaleStarted||save.world.finaleLost||save.world.finaleWon;entry.root.visible=forced||local>0;entry.root.scale.setScalar(.45+local*.9);entry.shard.material.opacity=forced?.72:.08+local*.64;entry.root.rotation.y=Math.sin(time*.18+entry.phase)*.12;});
  ruinVisuals.forEach(entry=>{entry.root.visible=ruin>=entry.threshold;entry.root.position.y=entry.root.visible?Math.sin(time*.65+entry.phase)*.035:-3;});
  if(save.world.finaleLost){const beacon=ensureResistanceBeacon();beacon.active=!(boss?.userData.active&&boss.userData.resistance);beacon.object.visible=true;if(beacon.object.userData.ring)beacon.object.userData.ring.rotation.z=time*.8;if(beacon.object.userData.signal)beacon.object.userData.signal.position.y=2+Math.sin(time*2.2)*.2;}else if(resistanceInteractable){resistanceInteractable.active=false;resistanceInteractable.object.visible=false;}
}

