    const rock=mesh(new THREE.DodecahedronGeometry(.35+rng()*.5,0),mat(rng()>.5?0x82918b:0x9c907e));rock.scale.y=.5+rng()*.5;rock.position.set(x,.3,z);rock.rotation.y=rng()*6;scene.add(rock);
