  const forecastVane=new THREE.Group(),forecastPole=mesh(new THREE.CylinderGeometry(.06,.1,2.2,7),mat(0x66747c)),forecastCanopy=mesh(new THREE.ConeGeometry(.72,.28,10),mat(0xd7bd63,{emissive:0x6b551d,emissiveIntensity:.25}),false);forecastPole.position.y=1.1;forecastCanopy.position.y=2.25;forecastCanopy.rotation.x=Math.PI;forecastVane.add(forecastPole,forecastCanopy);forecastVane.position.set(81,0,-45);scene.add(forecastVane);makeInteractable('story','forecast-vane',81,-45,'Inspect brass forecast umbrella',forecastVane,5.5);
