  const hemi=new THREE.HemisphereLight(0xcdeeff,0x445438,1.55);scene.add(hemi);sun=new THREE.DirectionalLight(0xffdba3,2.35);sun.position.set(-65,90,35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-70;sun.shadow.camera.right=70;sun.shadow.camera.top=70;sun.shadow.camera.bottom=-70;sun.shadow.bias=-.0004;scene.add(sun);
